      "Fill a bowl with salt water to rinse your fingers and season the onigiri (3 minutes).",
      "You can fill and shape the onigiri using two different methods: (3 minutes).",
      "Once the balls are reasonably cool, you need to protect them from drying out (3 minutes).",
      "The easiest way is to wrap them in cling wrap, or put them into an airtight plastic food container (3 minutes).",
      "When it is time to eat, take one rice ball, wrap it in a piece of nori, and eat away (3 minutes).",
