      "Add water and beat again before folding in caster sugar, vanilla and vinegar (3 minutes).",
      "Whip until the mixture holds its shape and stands in sharp peaks (3 minutes).",
      "Spread the mixture onto a baking sheet lined with parchment paper (3 minutes).",
      "Slow-bake the mixture at 150°C (300°F) to dry all the moisture and create the meringue, approximately 45 minutes (3 minutes).",
      "This leaves the outside of the pavlova a crisp crunchy shell, while the interior remains soft and moist (3 minutes).",
