    "name": "Polish Doughnuts (Paczki)",
    "minutes": 45,
    "servings": 12,
    "tags": [
      "dinner",
      "medium",
      "moderate",
      "vegetarian"
    ],
    "ingredients": [
      {
        "qty": 2,
        "unit": "tbsp",
        "item": "sugar"
      },
      {
        "qty": 2,
        "unit": "tbsp",
        "item": "softened unsalted butter"
      },
      {
        "qty": null,
        "unit": "",
        "item": "½ cup warm whole milk"
      },
      {
        "qty": null,
        "unit": "",
        "item": "¼ tsp vanilla extract"
      },
      {
        "qty": 1,
        "unit": "pinch",
        "item": "salt"
      },
      {
        "qty": 2,
        "unit": "",
        "item": "eggs"
      },
      {
        "qty": 1,
        "unit": "tsp",
        "item": "dry yeast"
      },
      {
        "qty": 2,
        "unit": "cup",
        "item": "all-purpose flour"
      },
      {
        "qty": null,
        "unit": "",
        "item": "Enough oil for deep frying (see notes)"
      },
      {
        "qty": null,
        "unit": "",
        "item": "Roughly 2½ cups jelly, jam, or custard, for filling (optional)"
      },
      {
        "qty": null,
        "unit": "",
        "item": "Powdered sugar, for dusting (optional)"
      }
    ],
    "steps": [
      "Whisk together the sugar, butter, milk, vanilla, salt, and eggs (3 minutes).",
      "Then, whisk in the yeast (3 minutes).",
      "While continuously stirring, add the flour ½ cup at a time until the mixture is a firm dough (3 minutes).",
      "Knead the dough for about 5 minutes (3 minutes).",
      "Put it back in the bowl, cover, and let it rise somewhere warm until it's twice its original size—this should take about 1½ hours (3 minutes).",
      "Pat the dough on a lightly floured surface, and roll the dough until it's about ½ inch thick (3 minutes).",
      "Cut out circles of dough and set aside (3 minutes).",
      "The exact size the circles should be is entirely up to your preference; the final product will have only a slightly larger diameter (3 minutes).",
      "You can roll out the excess dough again to cut more pączki (3 minutes).",
      "Let the dough rounds rise for about 30 minutes or until they've doubled in size (3 minutes).",
      "Heat oil to about 350°F in a deep pot or pan (3 minutes).",
      "Carefully spoon or slide a few pączki into the oil at a time to deep fry them until golden-brown."
    ],
